
.gal-shell {
  position: relative;
  width: 100%;
  max-width: 960px;
  margin: 0 auto;
  container-type: inline-size;
  --gal-topbar-h: 52px;
  --gal-body-h: calc(100cqw * 11 / 16 - var(--gal-topbar-h));
  display: flex;
  flex-direction: column;
  border: 1px solid var(--gal-border-strong);
  border-radius: var(--gal-radius-lg);
  overflow: visible;
  background: var(--gal-gradient-bg);
  box-shadow: var(--gal-shadow-card), 0 0 0 1px rgba(255, 255, 255, 0.04) inset;
}

.gal-shell__glow {
  position: absolute;
  border-radius: 50%;
  filter: blur(72px);
  pointer-events: none;
  opacity: 0.5;
  z-index: 0;

  &--pink {
    width: 220px;
    height: 220px;
    top: -60px;
    right: 10%;
    background: rgba(244, 114, 182, 0.28);
  }

  &--blue {
    width: 260px;
    height: 260px;
    bottom: 20%;
    left: -8%;
    background: rgba(96, 165, 250, 0.22);
  }
}

.gal-shell:fullscreen,
.gal-shell--expanded {
  max-width: none;
  width: 100vw;
  height: 100vh;
  margin: 0;
  border-radius: 0;
  --gal-body-h: calc(100vh - var(--gal-topbar-h));
}

.gal-shell--expanded {
  position: fixed;
  inset: 0;
  z-index: 99999;
}

.gal-body {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: flex-start;
  width: 100%;
}

.gal-left {
  flex: 1.1;
  min-width: 0;
  min-height: var(--gal-body-h);
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 14px;
  border-right: 1px solid var(--gal-border);
  background: rgba(14, 20, 36, 0.55);
  backdrop-filter: blur(8px);
}

.gal-left__media {
  flex-shrink: 0;
}

.gal-left__dialogue {
  flex: 0 0 auto;
}

.gal-left__choices {
  flex-shrink: 0;
  margin-top: auto;
}

.gal-left__media :deep(.media-panel) {
  height: auto;
}

.gal-left__choices :deep(.choice-panel) {
  height: auto;
}

.gal-right {
  flex: 0.9;
  flex-shrink: 0;
  min-width: 0;
  height: var(--gal-body-h);
  max-height: var(--gal-body-h);
  display: flex;
  flex-direction: column;
  background: rgba(10, 14, 26, 0.65);
  overflow: hidden;
  align-self: flex-start;
}
