
.choice-panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
  position: relative;
  z-index: 2;
}

.choice-panel__label {
  width: 100%;
}

.choice-panel__sending {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 10px;
  letter-spacing: 0;
  text-transform: none;
  color: var(--gal-pink);

  &::before {
    display: none;
  }
}

.choice-panel__options {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  flex-shrink: 0;
}

.choice-btn {
  padding: 10px 12px;
  border-radius: var(--gal-radius-sm);
  border: 1px solid var(--gal-border);
  background: var(--gal-gradient-card);
  color: var(--gal-text);
  font-size: 12px;
  text-align: left;
  cursor: pointer;
  line-height: 1.4;
  min-height: 40px;
  backdrop-filter: blur(6px);
  transition: all var(--gal-transition);

  &:hover:not(:disabled) {
    border-color: rgba(244, 114, 182, 0.4);
    background: var(--gal-pink-soft);
    transform: translateY(-1px);
  }

  &:disabled {
    opacity: 0.55;
    cursor: wait;
  }
}

.choice-panel__empty {
  grid-column: 1 / -1;
  padding: 14px;
  text-align: center;
  font-size: 12px;
  color: var(--gal-text-muted);
  border: 1px dashed var(--gal-border);
  border-radius: var(--gal-radius-sm);
  background: var(--gal-glass);
}

.choice-panel__input-row {
  display: flex;
  gap: 8px;
  flex-shrink: 0;
}

.choice-panel__input-wrap {
  flex: 1;
  min-width: 0;
  padding: 1px;
  border-radius: var(--gal-radius-pill);
  background: var(--gal-gradient-input);
}

.choice-panel__input {
  width: 100%;
  padding: 10px 14px;
  border-radius: var(--gal-radius-pill);
  border: none;
  background: rgba(10, 14, 26, 0.92);
  color: var(--gal-text);
  font-size: 13px;
  font-family: inherit;

  &:focus {
    outline: none;
  }

  &::placeholder {
    color: var(--gal-text-muted);
  }

  &:disabled {
    opacity: 0.6;
  }
}

.choice-panel__send {
  flex-shrink: 0;
}
