
.dialogue-panel {
  display: flex;
  flex-direction: column;
}

.dialogue-panel__label {
  width: 100%;
}

.dialogue-panel__progress {
  text-transform: none;
  letter-spacing: 0;
  font-variant-numeric: tabular-nums;
  font-size: 10px;
  padding: 2px 8px;
  border-radius: var(--gal-radius-pill);
  background: var(--gal-blue-soft);
  color: var(--gal-blue);

  &::before {
    display: none;
  }
}

.dialogue-panel__body {
  position: relative;
  padding: 12px;
  border-radius: var(--gal-radius-md);
  border: 1px solid var(--gal-border);
  background: var(--gal-gradient-card);
  backdrop-filter: blur(8px);
  cursor: pointer;
  transition: border-color var(--gal-transition);
  user-select: none;

  &:hover {
    border-color: rgba(96, 165, 250, 0.35);

    .dialogue-panel__hint {
      opacity: 0.5;
    }
  }
}

.dialogue-panel__hint {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  font-size: 12px;
  color: var(--gal-text-muted);
  opacity: 0;
  transition: opacity var(--gal-transition);
  pointer-events: none;

  &--prev {
    left: 10px;
  }

  &--next {
    right: 10px;
  }
}

.dialogue-bubble {
  display: flex;
  gap: 12px;
  align-items: flex-start;
}

.dialogue-bubble--narrator .dialogue-bubble__content {
  background: rgba(148, 163, 184, 0.08);
  border-style: dashed;
}

.dialogue-bubble--narrator .dialogue-bubble__name {
  color: var(--gal-text-muted);
}

.dialogue-bubble--other .dialogue-bubble__name {
  color: var(--gal-violet);
}

.dialogue-bubble__portrait {
  flex-shrink: 0;
  width: 96px;
  aspect-ratio: v-bind(PORTRAIT_ASPECT);
  border-radius: var(--gal-radius-sm);
  overflow: hidden;
  border: 2px solid transparent;
  background: linear-gradient(var(--gal-bg), var(--gal-bg)) padding-box,
    var(--gal-gradient-primary) border-box;
}

.dialogue-bubble__portrait--text {
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--gal-pink-soft);
  color: var(--gal-pink);
  font-weight: 700;
  font-size: 28px;
}

.dialogue-bubble__content {
  flex: 1;
  min-width: 0;
  padding: 12px 14px;
  border-radius: var(--gal-radius-md);
  background: rgba(15, 20, 38, 0.65);
  border: 1px solid var(--gal-border);
}

.dialogue-bubble__name {
  font-size: 11px;
  font-weight: 700;
  color: var(--gal-pink);
  margin-bottom: 6px;
}

.dialogue-bubble__text {
  font-size: 13px;
  line-height: 1.55;
  color: var(--gal-text);
  word-break: break-word;
}

.dialogue-panel__empty {
  min-height: 72px;
  padding: 16px;
}
