
.npc-panel {
  min-height: 0;
  overflow-y: auto;
}

.npc-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.npc-card__header {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}

.npc-card__avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  overflow: hidden;
  border: 2px solid transparent;
  background: linear-gradient(var(--gal-bg), var(--gal-bg)) padding-box,
    var(--gal-gradient-primary) border-box;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  color: var(--gal-pink);
}

.npc-card__title {
  flex: 1;
  min-width: 0;

  strong {
    display: block;
    font-size: 14px;
  }

  span {
    color: var(--gal-text-muted);
    font-size: 10px;
  }
}

.npc-card__chat {
  border: none;
  background: var(--gal-gradient-primary);
  color: #fff;
  box-shadow: var(--gal-shadow-glow);
}

.npc-card__stats,
.npc-card__abilities {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 8px;
  font-size: 11px;
  color: var(--gal-text-muted);

  i {
    margin-right: 3px;
    color: var(--gal-pink);
  }
}

.npc-card__abilities i {
  color: var(--gal-blue);
}

.npc-card__field {
  margin: 6px 0 0;
  line-height: 1.5;
  font-size: 11px;
  color: var(--gal-text-muted);

  strong {
    display: block;
    font-size: 10px;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--gal-text);
    margin-bottom: 2px;
  }
}
