
.chat-avatar {
  flex-shrink: 0;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  overflow: hidden;
  background: var(--gal-panel-light);
  border: 2px solid transparent;
  background-clip: padding-box;
  box-shadow: 0 0 0 2px rgba(129, 140, 248, 0.25);
  display: flex;
  align-items: center;
  justify-content: center;
}

.chat-avatar__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.chat-avatar__initial {
  font-size: 14px;
  font-weight: 700;
  background: var(--gal-gradient-primary);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  line-height: 1;
}
