
.map-panel {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-height: 0;
  overflow-y: auto;
}

.region-card__head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 6px;

  strong {
    font-size: 15px;
  }
}

.region-card__desc {
  font-size: 12px;
  color: var(--gal-text-muted);
  line-height: 1.5;
  margin: 0 0 12px;
}

.region-card__btn {
  width: 100%;
}
